/**
 * StaticLoopConditionalRowIndependentHelper fixture (#3912) — source lives in
 * the fixture-only root
 * (`fixtures/components/StaticLoopConditionalRowIndependentHelper.tsx`).
 *
 * The companion of `static-loop-conditional-function-helper` for a helper
 * call that takes no row argument (`isOn()`). Such a condition names neither
 * a row binding nor a signal, so it was dropped before the helper was
 * followed and the rows never switched.
 *
 * Snapshots in
 * `__snapshots__/static-loop-conditional-row-independent-helper.{html,client.js}`
 * are regenerated by `bun run packages/adapter-tests/scripts/snapshot.ts
 * static-loop-conditional-row-independent-helper`.
 */

import type { InteractionStep, JSXFixture } from '../src/types'
import { defineSharedFixture, type SharedFixtureSpec } from './_helpers'

const LISTS = ['fn', 'arrow'] as const

/** Both rows of every list show the same branch. */
function expectAll(tag: 'b' | 'i', text: string): InteractionStep[] {
  return LISTS.flatMap((list): InteractionStep[] => [
    { type: 'expectText', selector: `ul.${list} li:nth-child(1) ${tag}`, text },
    { type: 'expectText', selector: `ul.${list} li:nth-child(2) ${tag}`, text },
  ])
}

export const spec: SharedFixtureSpec = {
  id: 'static-loop-conditional-row-independent-helper',
  componentName: 'StaticLoopConditionalRowIndependentHelper',
  sourceRoot: 'fixture',
  description:
    'a static array row conditional whose condition is a row-independent local helper call switches when the signal the helper reads changes (#3912)',
  interactions: [
    ...expectAll('i', 'off'),
    { type: 'click', selector: '.inc' },
    ...expectAll('b', 'on'),
    { type: 'click', selector: '.reset' },
    ...expectAll('i', 'off'),
  ],
}

export const fixture: JSXFixture = defineSharedFixture(spec)
